import { LetterValue, PhraseSum, WordSum } from '../models/words';
import { SUMTYPES } from '../constants';
const english = 'abcdefghijklmnopqrstuvwxyz';
const englishReversed = english.split('').reverse().join('');

export const calculateOrdinal = ({ word, key }) =>
  word
    .split('')
    .map(
      (letter) =>
        new LetterValue(letter, key.indexOf(letter.toLowerCase()) + 1 || 0)
    );

const parseTwo = (twodigits, place) =>
  Number(twodigits.toString().charAt(place));

const calculateReduction = ({ word, key }) =>
  word.split('').map((letter) => {
    const count = key.indexOf(letter.toLowerCase()) + 1 || 0;
    let result = count > 9 ? parseTwo(count, 0) + parseTwo(count, 1) : count;
    return new LetterValue(
      letter,
      result > 9 ? parseTwo(result, 0) + parseTwo(result, 1) : result
    );
  });

const calculate = {
  english: (word) => calculateOrdinal({ word, key: english }),
  englishReversed: (word) => calculateOrdinal({ word, key: englishReversed }),
  reduction: (word) => calculateReduction({ word, key: english }),
  reductionReversed: (word) =>
    calculateReduction({ word, key: englishReversed }),
};

const phraseSumCore = ({ phrase = '', sumType = SUMTYPES.ENG }) => {
  const words = phrase
    .split(' ')
    .map((word) => word.trim().replace(',', ''))
    .filter((word) => word.length);

  const wordSums = words.map((word) => {
    const letterValues = calculate[sumType](word);
    const wordValue = Object.values(letterValues).reduce(
      (all, letterValue) => (all += letterValue.value),
      0
    );
    const averageLetter = Math.round(
      wordValue / Object.keys(letterValues).length
    );
    return new WordSum({ averageLetter, letterValues, word, wordValue });
  });

  const phraseValue = wordSums.reduce(
    (all, wordSum) => (all += wordSum.wordValue),
    0
  );

  return new PhraseSum({ phrase, phraseValue, wordSums });
};

export default phraseSumCore;
