export class LetterValue {
  constructor(letter, value) {
    this.letter = letter;
    this.value = value;
  }
}

export class WordSum {
  constructor({ averageLetter, letterValues, word, wordValue }) {
    this.averageLetter = averageLetter;
    this.letterValues = letterValues;
    this.word = word;
    this.wordValue = wordValue;
  }
}

export class PhraseSum {
  constructor({ phrase, phraseValue, wordSums }) {
    this.phrase = phrase;
    this.phraseValue = phraseValue;
    this.wordSums = wordSums;
  }
}
