import React, { useMemo } from 'react';
import styled from 'styled-components';
import { nanoid } from 'nanoid';
import { calculatePhraseSums } from '../util/word';
import useDebounce from '../util/debounce';

const PhraseWrapper = styled.div`
  padding-left: 16px;
`;

const PhraseSummary = styled.div`
  align-items: center;
  border: 1px solid rgba(255, 255, 255, 0);
  display: flex;
  padding: 24px 4px;
`;

const WordsWrapper = styled.div`
  display: flex;
  flex-wrap: wrap;
`;

const WordShape = styled.div`
  background-color: rgba(23, 23, 24, 1);
  border: 1px solid rgba(44, 44, 46, 1);
  display: flex;
  flex-direction: column;
  min-height: 292px;
  justify-content: flex-end;
  margin: 4px;
  padding: 0 16px 16px 16px;
`;

const LetterShapes = styled.div`
  background-color: rgba(23, 23, 24, 1);
  display: flex;
`;

const LetterColumn = styled.div`
  display: flex;
  flex-direction: column;
  height: 232px;
  justify-content: flex-end;
  margin: 8px;
  width: 8px;
`;

const LetterCell = styled.div`
  background-color: ${({ isScore }) =>
    isScore ? 'rgba(255, 159, 10, 1)' : null};
  font-size: 24px;
  height: ${({ cellHeight }) => (cellHeight ? `${cellHeight}px` : null)};
  margin-bottom: ${({ marginBottom }) =>
    marginBottom ? `${marginBottom}px` : 0};
  width: ${({ cellWidth }) => (cellWidth ? `${cellWidth}px` : '8px')};
`;

const LetterCellLetter = styled(LetterCell)`
  font-family: monospace;
  font-size: 24px;
  line-height: 0px;
  margin: 0;
  padding: 0;
  vertical-align: top;
`;

const AverageLetterCell = styled.div`
  background-color: ${({ isScore }) =>
    isScore ? 'rgba(48, 209, 88, 1)' : null};
  height: ${({ cellHeight }) => (cellHeight ? `${cellHeight - 3}px` : null)};
  width: 8px;
`;

const WordScore = styled.div`
  align-content: center;
  display: flex;
  font-size: 24px;
  flex-direction: column;
  margin-left: 16px;
  justify-content: center;
  text-align: center;
  width: 32px;
`;

const WordLengthBar = styled.div`
  background-color: rgba(94, 92, 230, 1);
  height: 8px;
  margin: 8px;
  margin-left: 4px;
  width: ${({ barWidth }) => (barWidth ? `${barWidth}px` : 0)};
`;

const calcuateHeight = ({
  multiplier,
  score,
  spacer = false,
  defaultHeight = 206,
}) => (spacer ? defaultHeight - score * multiplier : score * multiplier);

const calcBarHeight = (value) =>
  calcuateHeight({
    spacer: false,
    multiplier: 8,
    score: value,
  });
const calcBarNegative = (value) =>
  calcuateHeight({
    spacer: true,
    multiplier: 8,
    score: value,
  });

const AverageLetter = ({ averageLetter }) => {
  const averageLetterBarHeight = calcBarHeight(averageLetter);
  const averageLetterBarNegative = calcBarNegative(averageLetter);
  return (
    <LetterColumn>
      <AverageLetterCell cellHeight={averageLetterBarNegative} />
      <AverageLetterCell cellHeight={averageLetterBarHeight} isScore={true} />
    </LetterColumn>
  );
};

const Letters = ({ letterValues }) => {
  if (!letterValues) return null;
  const id = nanoid();

  return letterValues.map((letterValue, i) => {
    const barNegative = calcBarNegative(letterValue.value);
    const barHeight = calcBarHeight(letterValue.value);
    return (
      <LetterColumn key={`letter-column-${id}-${i}`}>
        <LetterCellLetter cellHeight={28} cellWidth={16} marginBottom={4}>
          {letterValue.letter}
        </LetterCellLetter>
        <LetterCell cellHeight={barNegative} />
        <LetterCell cellHeight={barHeight} isScore={true} />
      </LetterColumn>
    );
  });
};

const Phrase = ({ phrase, sumType }) => {
  const debouncedPhrase = useDebounce(phrase, 60);
  const { phrase: calculatedPhrase, wordSums, phraseValue } = useMemo(
    () =>
      debouncedPhrase.length && calculatePhraseSums(debouncedPhrase, sumType),
    [debouncedPhrase, sumType]
  );
  const id = nanoid();

  return (
    <PhraseWrapper>
      <PhraseSummary>
        {calculatedPhrase && calculatedPhrase.toUpperCase()} {phraseValue}
      </PhraseSummary>
      <WordsWrapper>
        {wordSums &&
          wordSums.map((wordSum, i) => (
            <WordShape key={`shape-${id}-${i}`}>
              <LetterShapes>
                <AverageLetter averageLetter={wordSum.averageLetter} />
                <Letters
                  averageLetter={wordSum.averageLetter}
                  letterValues={wordSum.letterValues}
                />
                <WordScore>{wordSum.wordValue}</WordScore>
              </LetterShapes>
              <WordLengthBar barWidth={wordSum.wordValue * 2} />
            </WordShape>
          ))}
      </WordsWrapper>
    </PhraseWrapper>
  );
};

export default Phrase;
