import React, { useState } from 'react';
import styled from 'styled-components';
import Header from './components/header';
import SearchBox from './components/search-box';
import Phrase from './components/phrase';

import { SUMTYPES } from './constants';

const WordShapeWrapper = styled.div`
  background-color: rgba(11, 11, 12, 1.0);
  height: 100%;
  min-height: 100vh;

`;

const HeaderContainer = styled.div`
  align-items: center;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  height: 72px;
`;

const App = () => {
  const [phrase, setPhrase] = useState('');
  const [sumType, setSumType] = useState(SUMTYPES.ENG);

  const handleChange = (e) => {
    const { target } = e;
    setPhrase(target.value);
  };

  const handleClose = () => setPhrase('');

  return (
    <WordShapeWrapper>
      <HeaderContainer>
        <Header />
        <SearchBox
          handleChange={handleChange}
          handleClose={handleClose}
          query={phrase}
        />
      </HeaderContainer>
      <Phrase phrase={phrase} sumType={sumType} />
    </WordShapeWrapper>
  );
};

export default App;
